using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using MiniErp.Models;using MiniErp.ViewModels;
namespace MiniErp.Controllers;
public class AccountController(SignInManager<ApplicationUser> signInManager,UserManager<ApplicationUser> userManager):Controller { [AllowAnonymous,HttpGet] public IActionResult Login(string? returnUrl=null){ViewData["ReturnUrl"]=returnUrl;return View();} [AllowAnonymous,HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Login(LoginViewModel model,string? returnUrl=null){ViewData["ReturnUrl"]=returnUrl;if(!ModelState.IsValid)return View(model);var result=await signInManager.PasswordSignInAsync(model.Email,model.Password,model.RememberMe,true);if(result.Succeeded)return LocalRedirect(Url.IsLocalUrl(returnUrl)?returnUrl:"/");ModelState.AddModelError(string.Empty,result.IsLockedOut?"La cuenta está bloqueada.":"Credenciales no válidas.");return View(model);} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Logout(){await signInManager.SignOutAsync();return RedirectToAction(nameof(Login));} [HttpGet] public IActionResult ChangePassword()=>View(); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> ChangePassword(ChangePasswordViewModel model){if(!ModelState.IsValid)return View(model);var user=await userManager.GetUserAsync(User);if(user is null)return Challenge();var result=await userManager.ChangePasswordAsync(user,model.CurrentPassword,model.NewPassword);if(!result.Succeeded){foreach(var error in result.Errors)ModelState.AddModelError(string.Empty,error.Description);return View(model);}await signInManager.RefreshSignInAsync(user);return RedirectToAction("Index","Home");} [AllowAnonymous] public IActionResult AccessDenied()=>View(); }
